{
  "name": "Pintores Pro - Expertos en Transformación",
  "description": "Sitio web profesional para servicios de pintura y renovación de interiores con un asistente IA inteligente y efectos interactivos de desplazamiento.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Service {
  id: string;
  title: string;
  description: string;
  icon: React.ReactNode;
  imageUrl: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY || "";

const SYSTEM_INSTRUCTION = `
Eres un asistente virtual experto para "Pintores Pro", una empresa de pintura profesional y reformas.
Tu objetivo es ayudar a los clientes con información sobre:
1. Precios aproximados: 
   - Habitación pequeña: desde 180€
   - Piso completo (60-80m2): desde 1200€
   - Pintura exterior: previa visita técnica (aproximadamente 15€-25€ por m2).
2. Ubicación: Operamos en toda el área metropolitana de Madrid y alrededores (hasta 50km).
3. Servicios: Pintura externa/interna, papel pintado, alisado de paredes, eliminar gotelé, encintado de pladur.
4. Tiempos: Una habitación suele tardar 1 día. Un piso completo de 3 a 5 días.

Reglas:
- Sé amable, profesional y conciso.
- Si no sabes algo de precios específicos, invita al usuario a dejar su teléfono o contactar por WhatsApp para un presupuesto personalizado gratuito.
- Responde siempre en español.
`;

export async function sendMessageToAI(message: string, history: {role: 'user' | 'model', text: string}[]) {
  try {
    const ai = new GoogleGenAI({ apiKey: API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [
        ...history.map(h => ({ role: h.role, parts: [{ text: h.text }] })),
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
    });

    return response.text || "Lo siento, no pude procesar tu solicitud en este momento.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Ups, parece que tengo problemas de conexión. ¿Podrías intentar contactarnos por WhatsApp directamente?";
  }
}

import React, { useState, useEffect } from 'react';

const ScrollPaintEffect: React.FC = () => {
  const [scrollProgress, setScrollProgress] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      const scrollY = window.scrollY;
      const windowHeight = window.innerHeight;
      const docHeight = document.documentElement.scrollHeight;

      // Calculate progress specifically for the hero section or first scroll
      const progress = Math.min(scrollY / (windowHeight * 0.8), 1);
      setScrollProgress(progress);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div className="relative w-full h-[80vh] overflow-hidden bg-slate-200">
      {/* Old Wall Background (Dirty/Damaged) */}
      <div 
        className="absolute inset-0 z-0 bg-cover bg-center grayscale contrast-125 opacity-70"
        style={{ 
          backgroundImage: 'url("https://images.unsplash.com/photo-1516962215378-7fa2e137ae93?auto=format&fit=crop&q=80&w=2000")',
          backgroundBlendMode: 'multiply'
        }}
      >
        <div className="absolute inset-0 bg-stone-900/40"></div>
      </div>

      {/* New Painted Wall (Clean) */}
      <div 
        className="absolute inset-0 z-10 bg-cover bg-center transition-all duration-75"
        style={{ 
          backgroundImage: 'url("https://images.unsplash.com/photo-1589939705384-5185137a7f0f?auto=format&fit=crop&q=80&w=2000")',
          clipPath: `inset(0 0 ${100 - (scrollProgress * 100)}% 0)`
        }}
      >
        {/* Subtle texture for the clean wall */}
        <div className="absolute inset-0 bg-white/10 backdrop-blur-[1px]"></div>
      </div>

      {/* Roller Visual */}
      <div 
        className="absolute left-1/2 -translate-x-1/2 z-20 pointer-events-none transition-all duration-75"
        style={{ 
          top: `${scrollProgress * 80}vh`,
          opacity: scrollProgress > 0 && scrollProgress < 1 ? 1 : 0
        }}
      >
        <div className="relative">
          {/* Paint Roller Icon/Image */}
          <div className="w-32 h-16 bg-blue-600 rounded-lg shadow-2xl flex items-center justify-center border-2 border-white">
            <div className="w-24 h-4 bg-white/20 rounded-full animate-pulse"></div>
          </div>
          <div className="w-1 h-32 bg-stone-700 mx-auto -mt-1"></div>
          <div className="w-8 h-12 bg-stone-800 rounded-b-xl mx-auto -mt-2"></div>

          {/* Drip Effect */}
          <div className="absolute -bottom-4 left-1/2 -translate-x-1/2 flex space-x-2">
            <div className="w-2 h-4 bg-blue-600 rounded-full animate-bounce"></div>
            <div className="w-2 h-6 bg-blue-500 rounded-full animate-bounce delay-100"></div>
          </div>
        </div>
      </div>

      {/* Content Overlay */}
      <div className="relative z-30 flex flex-col items-center justify-center h-full text-center px-4">
        <h1 className="text-5xl md:text-7xl font-serif text-white mb-6 drop-shadow-lg">
          Transformamos <br /> tu Espacio
        </h1>
        <p className="text-xl text-white/90 max-w-2xl font-light mb-8 drop-shadow-md">
          Pintura profesional con acabados impecables. Desliza para ver la magia de nuestra renovación.
        </p>
        <div className="flex flex-col sm:flex-row gap-4">
          <button 
            onClick={() => document.getElementById('services')?.scrollIntoView({ behavior: 'smooth' })}
            className="px-8 py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-full font-semibold transition-all transform hover:scale-105 shadow-xl"
          >
            Nuestros Servicios
          </button>
          <button 
            onClick={() => document.getElementById('contact')?.scrollIntoView({ behavior: 'smooth' })}
            className="px-8 py-4 bg-white/20 hover:bg-white/30 backdrop-blur-md text-white rounded-full font-semibold border border-white/30 transition-all shadow-xl"
          >
            Presupuesto Gratis
          </button>
        </div>

        {/* Scroll Indicator */}
        <div className="absolute bottom-10 animate-bounce flex flex-col items-center">
          <div className="w-6 h-10 border-2 border-white rounded-full flex justify-center pt-2">
            <div className="w-1 h-2 bg-white rounded-full"></div>
          </div>
          <span className="text-white text-xs mt-2 font-medium tracking-widest uppercase">Scroll</span>
        </div>
      </div>
    </div>
  );
};

export default ScrollPaintEffect;

