        <div className="flex flex-col items-center space-y-4 animate-bounce">
          <div className="w-[1px] h-12 bg-white/40"></div>
          <span className="text-white text-[9px] tracking-[0.4em] uppercase font-bold">Scroll</span>
        </div>
      </div>

      {/* Bottom context info */}
      <div className="absolute bottom-10 left-10 z-30 hidden md:block">
