import React, { useState, useEffect } from 'react';
import ScrollPaintEffect from './components/ScrollPaintEffect';
import AIChatAssistant from './components/AIChatAssistant';
import { GoogleGenAI } from "@google/genai";

const StatItem = ({ num, title }: { num: string; title: string }) => {
  const [count, setCount] = useState(0);
  const target = parseInt(num.replace(/\D/g, ''));

  useEffect(() => {
    let start = 0;
    const duration = 2000;
    const increment = target / (duration / 16);
    const timer = setInterval(() => {
      start += increment;
      if (start >= target) {
        setCount(target);
        clearInterval(timer);
      } else {
        setCount(Math.floor(start));
      }
    }, 16);
    return () => clearInterval(timer);
  }, [target]);

  return (
    <div className="text-center group p-8 glass rounded-[2rem] hover:scale-105 transition-transform duration-500">
      <div className="text-6xl md:text-8xl font-display italic mb-4 text-blue-600">
        {num.includes('+') ? `${count}+` : num.includes('%') ? `${count}%` : count}
      </div>
      <div className="text-[10px] uppercase tracking-[0.4em] font-bold text-slate-400">{title}</div>
    </div>
  );
};

const FAQItem = ({ question, answer }: { question: string; answer: string }) => {
  const [isOpen, setIsOpen] = useState(false);
  return (
    <div className="border-b border-stone-100 last:border-0 overflow-hidden text-slate-900">
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="w-full py-8 flex justify-between items-center text-left group transition-all"
      >
        <span className="text-xl md:text-2xl font-display group-hover:text-blue-600 transition-colors pr-8">{question}</span>
        <div className={`w-10 h-10 rounded-full flex items-center justify-center border border-stone-100 transition-all ${isOpen ? 'bg-blue-600 border-blue-600 text-white rotate-180' : 'text-blue-600'}`}>
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7"/></svg>
        </div>
      </button>
      <div className={`transition-all duration-500 ease-in-out ${isOpen ? 'max-h-[400px] opacity-100 pb-12' : 'max-h-0 opacity-0'}`}>
        <p className="text-slate-500 font-light leading-relaxed max-w-3xl text-lg">{answer}</p>
      </div>
    </div>
  );
};

