import React, { useState, useEffect } from 'react';
import ScrollPaintEffect from './components/ScrollPaintEffect';
import AIChatAssistant from './components/AIChatAssistant';
import { GoogleGenAI } from "@google/genai";

const StatItem = ({ num, title }: { num: string; title: string }) => {
  const [count, setCount] = useState(0);
  const target = parseInt(num.replace(/\D/g, ''));

  useEffect(() => {
    let start = 0;
    const duration = 2000;
    const increment = target / (duration / 16);
    const timer = setInterval(() => {
      start += increment;
      if (start >= target) {
        setCount(target);
        clearInterval(timer);
      } else {
        setCount(Math.floor(start));
      }
    }, 16);
    return () => clearInterval(timer);
  }, [target]);

  return (
    <div className="text-center group p-10 glass rounded-[3rem] hover:scale-105 transition-all duration-700 border border-white/20 shadow-xl">
      <div className="text-6xl md:text-8xl font-display italic mb-4 bg-gradient-to-br from-blue-600 to-indigo-800 bg-clip-text text-transparent">
        {num.includes('+') ? `${count}+` : num.includes('%') ? `${count}%` : count}
      </div>
      <div className="text-[10px] uppercase tracking-[0.4em] font-bold text-slate-400 group-hover:text-blue-600 transition-colors">{title}</div>
    </div>
  );
};

const FAQItem = ({ question, answer }: { question: string; answer: string }) => {
