import React, { useState, useEffect } from 'react';

const ScrollPaintEffect: React.FC = () => {
  const [scrollProgress, setScrollProgress] = useState(0);
  const [isHanging, setIsHanging] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      const scrollY = window.scrollY;

      // SENSIBILIDAD ULTRA-RÁPIDA: El efecto se completa en 200px
      const progress = Math.min(scrollY / 200, 1);
      setScrollProgress(progress);

      // El rodillo queda en modo decorativo después del scroll inicial
      if (scrollY > 350) {
        setIsHanging(true);
      } else {
        setIsHanging(false);
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div className="relative w-full h-[100vh] overflow-hidden bg-stone-100">
      {/* Capa Base: Antes de pintar (Gris) */}
      <div 
        className="absolute inset-0 z-0 bg-cover bg-center transition-all duration-700 ease-out"
        style={{ 
          backgroundImage: 'url("https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&q=80&w=2000")',
          filter: `grayscale(${100 - (scrollProgress * 80)}%) brightness(${0.5 + (scrollProgress * 0.5)})`,
          opacity: 0.7 + (scrollProgress * 0.3),
        }}
      />

      {/* Capa de Revelado: PARED MARRÓN MORADO + SOFÁ BEIGE + MANTA MARRÓN */}
      <div 
        className="absolute inset-0 z-10 bg-cover bg-center origin-top"
        style={{ 
          backgroundImage: 'url("https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?auto=format&fit=crop&q=80&w=2000")',
          clipPath: `inset(0 0 ${100 - (scrollProgress * 100)}% 0)`,
        }}
      >
        <div className="absolute inset-0 bg-indigo-950/5 mix-blend-multiply pointer-events-none"></div>
      </div>

      {/* Contenido Hero */}
      <div className="relative z-30 flex flex-col items-center justify-center h-full text-center px-6 pointer-events-none">
        <div className={`transition-all duration-1000 ${scrollProgress > 0.95 ? 'opacity-0 -translate-y-20' : 'opacity-100'}`}>
          <div className="mb-10">
            <span 
              className={`inline-block px-10 py-4 border transition-all duration-500 text-[10px] font-bold tracking-[0.6em] uppercase backdrop-blur-md rounded-full ${
