      />

      {/* CAPA 2: Imagen Revelada */}
      <div 
        className="absolute inset-0 z-10 bg-cover bg-center origin-top pointer-events-none"
        style={{ 
          backgroundImage: 'url("https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?auto=format&fit=crop&q=80&w=2000")',
          clipPath: `inset(0 0 calc(${100 - (scrollProgress * 100)}% - ${offsetPixels * (1 - scrollProgress)}px) 0)`,
        }}
      >
        <div className="absolute inset-0 bg-gradient-to-b from-transparent via-transparent to-black/30"></div>
      </div>

      {/* TEXTO HERO */}
      <div className="relative z-30 flex flex-col items-center justify-center h-full text-center px-6 pointer-events-none">
        <div className={`transition-all duration-700 ${scrollProgress > 0.95 ? 'opacity-0 -translate-y-20' : 'opacity-100'}`}>
          <div className="mb-8">
            <span className={`inline-block px-8 py-3 border transition-all duration-500 text-[10px] font-bold tracking-[0.6em] uppercase backdrop-blur-md rounded-full ${scrollProgress > 0.1 ? 'bg-black text-white border-black' : 'bg-white/10 text-white border-white/20'}`}>
              Excelencia en Acabados
            </span>
          </div>
          <h1 className="text-6xl md:text-[10rem] font-display italic text-white mb-8 leading-[0.8] drop-shadow-[0_10px_40px_rgba(0,0,0,0.9)]">
