              tiene un Color
            </span>
          </h1>
        </div>
      </div>

      {/* EL CLAVO (Solo visible al final) */}
      <div 
        className="absolute z-40 transition-opacity duration-500"
        style={{ 
          top: '50%', 
          left: '94%', 
          opacity: isHanging ? 1 : 0,
          transform: 'translate(-50%, -50%)'
        }}
      >
        <div className="w-3 h-3 bg-stone-400 rounded-full shadow-[inset_0_2px_4px_rgba(0,0,0,0.5),0_1px_2px_rgba(255,255,255,0.2)]"></div>
