      {/* RODILLO LINE-ART (OUTLINE) */}
      <div 
        className="absolute z-50 transition-all duration-300 ease-out pointer-events-none"
        style={{ 
          top: isHanging ? '50%' : `calc(${scrollProgress * 100}% + ${offsetPixels}px)`,
          left: isHanging ? '94.2%' : '50%',
          transform: `translateX(-50%) translateY(-50%) ${isHanging ? 'rotate(90deg) scale(0.35)' : 'rotate(0deg)'}`,
          opacity: scrollProgress > 0.01 ? 1 : 0
        }}
      >
        <div className="relative flex flex-col items-center justify-center">
          {/* Animación de Goteo (Solo cuando está colgado) */}
          {isHanging && (
            <>
              <div className="paint-drip absolute top-[130px] left-[150px] w-2 h-2 bg-white rounded-full blur-[1px]"></div>
              <div className="paint-drip absolute top-[130px] left-[300px] w-2.5 h-2.5 bg-white rounded-full blur-[1px]" style={{ animationDelay: '1s' }}></div>
