import React, { useState, useEffect, useRef } from 'react';

const ScrollPaintEffect: React.FC = () => {
  const [scrollProgress, setScrollProgress] = useState(0);
  const [isHanging, setIsHanging] = useState(false);
  const requestRef = useRef<number>(null);

  useEffect(() => {
    const handleScroll = () => {
      const scrollY = window.scrollY;

      // Velocidad ultra-rápida: Se completa en 250px
      const progress = Math.min(scrollY / 250, 1);

      // Optimizamos la actualización para que sea fluida en móviles
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
      requestRef.current = requestAnimationFrame(() => {
        setScrollProgress(progress);
        // Se engancha al clavo un poco después de terminar de pintar
        setIsHanging(scrollY > 350);
      });
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => {
      window.removeEventListener('scroll', handleScroll);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, []);

  // Altura base del rodillo (más bajo aún para ver el antes/después)
  const offsetPixels = 220; 

  return (
    <div className="relative w-full h-[100vh] overflow-hidden bg-stone-900">
      <style>{`
        @keyframes paint-drip {
          0% { transform: scaleY(0); opacity: 0; }
          20% { transform: scaleY(1); opacity: 1; }
          80% { opacity: 1; transform: translateY(40px) scaleY(0.8); }
          100% { transform: translateY(80px) scaleY(0); opacity: 0; }
        }
        .drip {
          width: 4px;
          background: white;
          border-radius: 0 0 4px 4px;
          position: absolute;
          transform-origin: top;
          animation: paint-drip 2.5s infinite ease-in-out;
        }
      `}</style>

      {/* Capa Antes */}
      <div 
        className="absolute inset-0 z-0 bg-cover bg-center"
        style={{ 
          backgroundImage: 'url("https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&q=80&w=2000")',
          filter: `grayscale(${100 - (scrollProgress * 90)}%) brightness(${0.3 + (scrollProgress * 0.7)})`,
        }}
      />

      {/* Capa Después (Pintada) */}
      <div 
        className="absolute inset-0 z-10 bg-cover bg-center origin-top pointer-events-none"
        style={{ 
          backgroundImage: 'url("https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?auto=format&fit=crop&q=80&w=2000")',
          clipPath: `inset(0 0 calc(${100 - (scrollProgress * 100)}% - ${offsetPixels * (1 - scrollProgress)}px) 0)`,
          willChange: 'clip-path'
        }}
      >
        <div className="absolute inset-0 bg-gradient-to-b from-transparent via-transparent to-black/40"></div>
      </div>

      {/* Texto Hero */}
      <div className="relative z-30 flex flex-col items-center justify-center h-full text-center px-6 pointer-events-none">
        <div className={`transition-all duration-700 ${scrollProgress > 0.9 ? 'opacity-0 scale-95' : 'opacity-100 scale-100'}`}>
          <div className="mb-6">
            <span className="inline-block px-6 py-2 border border-white/20 text-[9px] font-bold tracking-[0.5em] uppercase backdrop-blur-md rounded-full text-white bg-white/5">
              Pintura Profesional
            </span>
          </div>
          <h1 className="text-5xl md:text-[9rem] font-display italic text-white mb-4 leading-[0.85] drop-shadow-2xl">
            La Perfección <br /> 
            <span className="font-bold not-italic bg-gradient-to-r from-white via-indigo-100 to-white bg-clip-text text-transparent">
              tiene un Color
            </span>
          </h1>
        </div>
      </div>

      {/* El Clavo Metálico */}
      <div 
        className="absolute z-40 transition-all duration-500 ease-in-out"
        style={{ 
          top: '50%', 
          left: '92%', 
          opacity: isHanging ? 1 : 0,
          transform: `translate(-50%, -50%) scale(${isHanging ? 1 : 0.5})`
        }}
      >
        <div className="w-4 h-4 bg-stone-500 rounded-full border-b-2 border-black/40 shadow-lg relative">
          <div className="absolute top-1 left-1 w-1 h-1 bg-white/30 rounded-full"></div>
        </div>
      </div>

      {/* El Rodillo (Optimizado para móviles) */}
      <div 
        className="absolute z-50 transition-all duration-500 cubic-bezier(0.23, 1, 0.32, 1) pointer-events-none"
        style={{ 
          top: isHanging ? '50.5%' : `calc(${scrollProgress * 100}% + ${offsetPixels}px)`,
          left: isHanging ? '92.5%' : '50%',
          transform: `translate3d(-50%, -50%, 0) ${isHanging ? 'rotate(90deg) scale(0.3)' : 'rotate(0deg) scale(1)'}`,
          opacity: scrollProgress > 0.01 ? 1 : 0,
          willChange: 'transform, top, left'
        }}
      >
        <div className="relative">
          {/* Gotas de pintura (Solo cuando está colgado) */}
          {isHanging && (
            <div className="absolute top-[130px] left-0 w-full h-full pointer-events-none">
              <div className="drip" style={{ left: '160px', animationDelay: '0s', height: '15px' }}></div>
              <div className="drip" style={{ left: '300px', animationDelay: '0.8s', height: '22px' }}></div>
              <div className="drip" style={{ left: '440px', animationDelay: '1.5s', height: '12px' }}></div>
            </div>
          )}

          <svg 
            viewBox="0 0 600 480" 
            className="w-[260px] md:w-[500px] h-auto drop-shadow-[0_0_40px_rgba(255,255,255,0.5)]"
          >
            {/* Solo contornos puros */}
            <rect 
              x="120" y="40" width="360" height="90" rx="15" 
              stroke="white" strokeWidth="8" fill="none"
            />
            <path d="M105 55C105 50 110 45 120 45V125C110 125 105 120 105 115V55Z" stroke="white" strokeWidth="6" fill="none"/>
            <path d="M495 55C495 50 490 45 480 45V125C490 125 495 120 495 115V55Z" stroke="white" strokeWidth="6" fill="none"/>
            <path 
              d="M495 85H525C535 85 540 90 540 100V200C540 210 535 215 525 215H310C300 215 295 220 295 230V260" 
              stroke="white" strokeWidth="10" strokeLinecap="round" fill="none"
            />
            <rect x="260" y="260" width="80" height="180" rx="40" stroke="white" strokeWidth="8" fill="none"/>
          </svg>

          {/* Línea de presión de luz */}
          <div 
            className={`absolute top-[90px] left-1/2 -translate-x-1/2 w-[200px] md:w-[350px] h-[4px] bg-white shadow-[0_0_40px_#fff] transition-opacity duration-300 ${isHanging ? 'opacity-0' : 'opacity-100'}`}
          />
        </div>
      </div>

      {/* Indicador inferior */}
      <div className={`absolute bottom-8 left-1/2 -translate-x-1/2 z-40 transition-all duration-1000 ${scrollProgress > 0.05 ? 'opacity-0' : 'opacity-100 animate-bounce'}`}>
        <div className="flex flex-col items-center space-y-2">
          <div className="w-[1px] h-8 bg-white/30"></div>
          <span className="text-white/40 text-[8px] tracking-[0.8em] uppercase font-bold">Desliza</span>
        </div>
      </div>
    </div>
  );
};

