import React, { useState, useEffect, useRef } from 'react';

const ScrollPaintEffect: React.FC = () => {
  const [scrollProgress, setScrollProgress] = useState(0);
  const [isAtBottom, setIsAtBottom] = useState(false);
  const requestRef = useRef<number>(null);

  useEffect(() => {
    const handleScroll = () => {
      const scrollY = window.scrollY;

      // Velocidad de pintado: Se completa en 300px
      const progress = Math.min(scrollY / 300, 1);

      if (requestRef.current) cancelAnimationFrame(requestRef.current);
      requestRef.current = requestAnimationFrame(() => {
        setScrollProgress(progress);
        // Se considera "en la base" cuando el scroll supera el umbral de pintado
        setIsAtBottom(scrollY > 320);
      });
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => {
      window.removeEventListener('scroll', handleScroll);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, []);

  // Altura inicial del rodillo para que se vea bien desde el principio
  const offsetPixels = 220; 

  return (
    <div className="relative w-full h-[100vh] overflow-hidden bg-stone-900">
      <style>{`
        @keyframes puddle-grow {
          0% { transform: scaleX(0) scaleY(0); opacity: 0; }
          100% { transform: scaleX(1) scaleY(1); opacity: 1; }
        }
        @keyframes drip-fall {
          0% { transform: translateY(0) scale(1); opacity: 0; }
          20% { opacity: 1; }
          100% { transform: translateY(60px) scale(0.5); opacity: 0; }
        }
        .puddle {
          animation: puddle-grow 1s forwards cubic-bezier(0.16, 1, 0.3, 1);
        }
        .drip-active {
          animation: drip-fall 2s infinite ease-in;
        }
      `}</style>

      {/* Capa de fondo (Antes) */}
      <div 
        className="absolute inset-0 z-0 bg-cover bg-center"
        style={{ 
          backgroundImage: 'url("https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&q=80&w=2000")',
          filter: `grayscale(${100 - (scrollProgress * 90)}%) brightness(${0.2 + (scrollProgress * 0.8)})`,
        }}
      />

      {/* Capa Pintada (Después) */}
      <div 
        className="absolute inset-0 z-10 bg-cover bg-center origin-top pointer-events-none"
        style={{ 
          backgroundImage: 'url("https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?auto=format&fit=crop&q=80&w=2000")',
          clipPath: `inset(0 0 calc(${100 - (scrollProgress * 100)}% - ${offsetPixels * (1 - scrollProgress)}px) 0)`,
          willChange: 'clip-path'
        }}
      >
        <div className="absolute inset-0 bg-gradient-to-b from-transparent via-transparent to-black/50"></div>
      </div>

      {/* Hero Text */}
      <div className="relative z-30 flex flex-col items-center justify-center h-full text-center px-6 pointer-events-none">
        <div className={`transition-all duration-700 ${scrollProgress > 0.85 ? 'opacity-0 -translate-y-10' : 'opacity-100 translate-y-0'}`}>
          <div className="mb-6">
            <span className="inline-block px-6 py-2 border border-white/20 text-[9px] font-bold tracking-[0.5em] uppercase backdrop-blur-md rounded-full text-white bg-white/5">
              Pintura Profesional
            </span>
          </div>
          <h1 className="text-5xl md:text-[9rem] font-display italic text-white mb-4 leading-[0.85] drop-shadow-2xl">
            La Perfección <br /> 
            <span className="font-bold not-italic bg-gradient-to-r from-white via-indigo-100 to-white bg-clip-text text-transparent">
              tiene un Color
            </span>
          </h1>
        </div>
      </div>

      {/* CHARCO DE PINTURA (Solo aparece al final) */}
      {isAtBottom && (
        <div className="absolute bottom-0 left-1/2 -translate-x-1/2 z-40 w-full flex justify-center pointer-events-none">
          <svg 
            viewBox="0 0 400 100" 
            className="puddle w-[300px] md:w-[600px] h-auto drop-shadow-2xl"
            fill="#0a0a0a" // Negro profundo para el charco
          >
            <path d="M0,50 Q10,20 50,25 T100,10 T150,30 T200,20 T250,40 T300,15 T350,35 T400,50 L400,100 L0,100 Z" />
          </svg>
        </div>
      )}

      {/* EL RODILLO */}
      <div 
        className="absolute z-50 transition-all duration-700 cubic-bezier(0.16, 1, 0.3, 1) pointer-events-none"
        style={{ 
          top: isAtBottom ? '91%' : `calc(${scrollProgress * 100}% + ${offsetPixels}px)`,
          left: '50%',
          transform: `translate3d(-50%, -50%, 0) scale(${isAtBottom ? 0.7 : 1.1})`,
          opacity: scrollProgress > 0.01 ? 1 : 0,
          willChange: 'transform, top'
        }}
      >
        <div className="relative flex flex-col items-center">
          {/* Gotas de pintura cayendo al charco */}
          {isAtBottom && (
            <div className="absolute top-[100px] w-full flex justify-center space-x-20">
              <div className="drip-active w-1.5 h-1.5 bg-black rounded-full" style={{ animationDelay: '0.2s' }}></div>
              <div className="drip-active w-2 h-2 bg-black rounded-full" style={{ animationDelay: '1.1s' }}></div>
              <div className="drip-active w-1 h-1 bg-black rounded-full" style={{ animationDelay: '2.5s' }}></div>
            </div>
          )}

          <svg 
            viewBox="0 0 600 480" 
            className="w-[240px] md:w-[480px] h-auto drop-shadow-[0_0_50px_rgba(255,255,255,0.3)]"
          >
            {/* Outline limpio del rodillo */}
            <rect 
              x="120" y="40" width="360" height="90" rx="15" 
              stroke="white" strokeWidth="8" fill="none"
            />
            <path d="M105 55C105 50 110 45 120 45V125C110 125 105 120 105 115V55Z" stroke="white" strokeWidth="6" fill="none"/>
            <path d="M495 55C495 50 490 45 480 45V125C490 125 495 120 495 115V55Z" stroke="white" strokeWidth="6" fill="none"/>
            <path 
              d="M495 85H525C535 85 540 90 540 100V200C540 210 535 215 525 215H310C300 215 295 220 295 230V260" 
              stroke="white" strokeWidth="10" strokeLinecap="round" fill="none"
            />
            <rect x="260" y="260" width="80" height="180" rx="40" stroke="white" strokeWidth="8" fill="none"/>
          </svg>

          {/* Línea de presión (solo durante el pintado) */}
          <div 
            className={`absolute top-[90px] left-1/2 -translate-x-1/2 w-[180px] md:w-[320px] h-[4px] bg-white shadow-[0_0_40px_#fff] transition-opacity duration-300 ${isAtBottom ? 'opacity-0' : 'opacity-100'}`}
          />
        </div>
      </div>

      {/* Indicador de scroll */}
      <div className={`absolute bottom-8 left-1/2 -translate-x-1/2 z-40 transition-all duration-1000 ${scrollProgress > 0.05 ? 'opacity-0' : 'opacity-100 animate-bounce'}`}>
        <div className="flex flex-col items-center space-y-2">
          <div className="w-[1px] h-8 bg-white/30"></div>
          <span className="text-white/40 text-[8px] tracking-[0.8em] uppercase font-bold">Pintar</span>
        </div>
      </div>
    </div>
  );
};

